async function startCardRun(){if(!state.authenticated||!state.user)return null;try{return await api('activity/start',{mode:'cards'});}catch(error){toast('게임 기록 연결 실패 · 완료 시 재연결 · 카드 상태는 별도 저장');return {startFailed:true,message:error.message};}}
async function completeCardGame(detail){
  if(!['write','match'].includes(detail.mode))return {points:0};
  let pendingRun=cardsRun,run=await pendingRun;
  if(!state.authenticated||!state.user)return {points:0,awarded:false};
  try{
    if(!run||run.startFailed){
      const replacement=startCardRun();
      if(cardsRun===pendingRun)cardsRun=replacement;
      pendingRun=replacement;run=await pendingRun;
      if(!run||run.startFailed)throw new Error(run?.message||'게임 기록 연결 실패');
    }
    let result;
    for(let attempt=0;attempt<2;attempt++){
      try{result=await api('activity/complete',{runId:run.runId,cardIds:detail.cardIds,correct:detail.correct,total:detail.total});break;}
      catch(error){
        if(attempt===0&&error.status===409&&Number(error.retryAfterMs)>0&&Number(error.retryAfterMs)<=8000){await new Promise(resolve=>setTimeout(resolve,Number(error.retryAfterMs)+30));continue;}
        throw error;
      }
    }
    await refresh();
    if(cardsRun===pendingRun)cardsRun=startCardRun();
    return result;
  }catch(error){toast('완료 기록 저장 실패 · 같은 결과로 재시도');throw error;}
}
