const ROUTE_VIEWS=['home','quests','library','slides','rankings','profile','arcade'];
const ROUTE_INDEX='ajEnglishRouteIndex';
function routeIndex(){const value=history.state?.[ROUTE_INDEX];return Number.isInteger(value)?value:null;}
let routePosition=routeIndex()??0;
function routeState(index){return {...(history.state&&typeof history.state==='object'?history.state:{}),[ROUTE_INDEX]:index};}
function initializeRouteHistory(){history.replaceState(routeState(routePosition),'',location.href);}
function writeRoute(next,replace=false){
  const url=new URL(location.href);
  url.hash=next;
  if(next==='slides'&&selectedChapterId)url.searchParams.set('chapter',selectedChapterId);else url.searchParams.delete('chapter');
  const method=replace||typeof history.pushState!=='function'?'replaceState':'pushState';
  if(method==='pushState')routePosition++;
  history[method](routeState(routePosition),'',url.pathname+url.search+url.hash);
}
function restoreRoute(){
  const current=routeIndex();
  if(current!==null&&current!==routePosition&&typeof history.go==='function')history.go(routePosition-current);
  else writeRoute(view,true);
}
async function navigate(next,options={}){
  if(!ROUTE_VIEWS.includes(next))return false;
  const epoch=++routeEpoch;
  const requested=options.chapter===undefined?selectedChapterId:options.chapter;
  const changingChapter=next==='slides'&&requested!==selectedChapterId;
  if(next===view&&!changingChapter){
    if(options.fromHistory&&Number.isInteger(options.historyIndex))routePosition=options.historyIndex;
    if(!options.fromHistory)restoreRoute();
    return true;
  }
  if(view==='slides'&&slidesController&&!(await slidesController.flush())){
    if(epoch===routeEpoch){restoreRoute();toast('필기 저장 확인 후 이동');}
    return false;
  }
  if(epoch!==routeEpoch)return false;
  selectedChapterId=requested;view=next;
  if(options.fromHistory&&Number.isInteger(options.historyIndex))routePosition=options.historyIndex;
  writeRoute(next,options.fromHistory===true||options.replace===true);
  render();$('#app').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});return true;
}
function routeFromAddress(){
  const next=location.hash.slice(1);
  if(!ROUTE_VIEWS.includes(next))return;
  const chapter=next==='slides'?new URL(location.href).searchParams.get('chapter'):selectedChapterId;
  let index=routeIndex();
  if(index===null){index=routePosition+1;history.replaceState(routeState(index),'',location.href);}
  navigate(next,{chapter,fromHistory:true,historyIndex:index});
}

