function weekCalendar(){const today=kstDate(),d=new Date(today+'T00:00:00Z'),weekday=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-weekday);return `<div class="week-days">${Array.from({length:7},(_,i)=>{const t=new Date(d);t.setUTCDate(d.getUTCDate()+i);const key=t.toISOString().slice(0,10),active=state.progress.activity?.some(a=>a.date===key&&a.points>0);return `<div class="week-day ${active?'done':''} ${key===today?'today':''}"><span>${['월','화','수','목','금','토','일'][i]}</span><b>${active?'✓':t.getUTCDate()}</b></div>`;}).join('')}</div>`;}
