function weeklySyllabus(){const days=COURSE_DATA[course],next=nextDay();(weeklySyllabusTarget||$('#app')).innerHTML=`<div class="campaign-intro"><p class="eyebrow">WEEKLY CLASS</p><h2>주간 수업</h2><p>주 1시간 수업 · 매일 20분 복습</p>${courseSwitch()}<div class="campaign-meta"><span>${courseNames[course]}</span><span>${days.filter(d=>done(d.id)).length} / 7 STAGES COMPLETE</span></div></div><section class="campaign-route" aria-label="7일 학습 캠페인">${days.map(d=>`<article class="campaign-stop ${done(d.id)?'completed':d.id===next.id?'current':''}"><div class="campaign-number">${done(d.id)?'✓':String(d.id).padStart(2,'0')}</div><div class="campaign-copy"><span class="eyebrow">DAY ${d.id} · 20 MIN · ${done(d.id)?'COMPLETE':'SPEAKING'}</span><h3 class="campaign-title">${esc(d.title)}</h3><p>${esc(d.subtitle)}</p><ul class="campaign-expressions">${d.phrases.map(p=>`<li lang="en">${esc(p.en)}</li>`).join('')}</ul></div><button class="campaign-start" data-start="${d.id}" aria-label="${esc(d.title)} ${done(d.id)?'다시 연습':'시작'}">${icon(done(d.id)?'check':'arrow')}</button></article>`).join('')}</section><section class="panel class-bridge"><p class="eyebrow">NEXT CLASS / 60 MIN</p><h3>다음 수업 준비</h3><div class="grid-3"><div><b>10분 · 지난 수업 복습</b><p>학습 문장 및 어려운 표현 확인</p></div><div><b>35분 · 회화 연습</b><p>이름·직업·목표를 바꾼 역할극</p></div><div><b>15분 · 다음 수업 준비</b><p>다음 수업 문장 3개 선정</p></div></div><label class="field">수업 질문<textarea id="class-note" placeholder="예: keep me in the loop를 어느 상황에 쓰면 좋을까요?" maxlength="2000"></textarea></label><button class="btn secondary small" data-save-note>이 기기에 메모 저장</button><p class="tiny">메모·별표: 이 브라우저 저장 · 캐릭터·포인트: 계정 저장</p></section>`;try{$('#class-note').value=localStorage.getItem('lil-class-note')||'';}catch{}}
