function mvpDeadline(month){const [year,number]=month.split('-').map(Number);return year+'.'+String(number).padStart(2,'0')+'.'+new Date(Date.UTC(year,number,0)).getUTCDate()+' 23:59 집계 마감';}

async function rankings(){const month=rankMonth;$('#app').innerHTML=`<div class="section-head"><div><p class="eyebrow">MONTHLY MVP LEAGUE</p><h2>월간 MVP</h2><p>우리 반 종합·학습·게임 순위</p></div><input class="month-input" type="month" id="rank-month" value="${month}" max="${kstDate().slice(0,7)}" aria-label="MVP 월 선택"></div><div class="filters">${[['overall','종합 MVP'],['study','학습 MVP'],['game','게임 MVP']].map(([key,text])=>`<button class="filter ${mvpCategory===key?'active':''}" data-mvp-tab="${key}">${text}</button>`).join('')}</div><section class="panel" id="ranking-content"><p>학습 기록 불러오는 중</p></section><section class="panel rules"><div class="mvp-rules-head"><h3>월간 MVP · 집계 기준</h3><span class="chip">${esc(mvpDeadline(month))} · 한국 시간</span></div><div class="grid-3"><div><b>학습 MVP</b><p>20분 퀘스트 최대 100 XP · 단어장 복습 최대 30 XP · 카드별 하루 1회 지급</p></div><div><b>게임 MVP</b><p>첫 정답·완료 보상 합산 하루 최대 40 XP · 실제 지급 포인트 기준</p></div><div><b>종합 MVP</b><p>학습·게임 점수 합산 · 동점은 포인트를 얻은 학습일 수 비교 · 같으면 공동 순위</p></div></div><p class="mvp-rules-note">매월 1일 새 순위 집계 · 지난달 기록 조회 가능. 학습 완료 XP·코인과 1·7·20일 학습 배지는 순위와 별도로 확인.</p></section>`;try{const data=await api('mvp?month='+month);if(view!=='rankings'||month!==rankMonth)return;const target=$('#ranking-content');if(!data.room){target.innerHTML=`<div class="empty"><span class="empty-symbol"></span><h3>우리 반 연결</h3><p>로그인 → 캐릭터 저장 → 반 코드 입력</p><button class="btn primary" data-room>우리 반 만들기 / 참여하기</button></div>`;return;}const rows=data.categories[mvpCategory]||[],winners=rows.filter(r=>r.categoryPoints>0&&r.rank<=3);target.innerHTML=`<div class="section-head"><div><p class="eyebrow">${esc(data.room.name)}</p><h3>${Number(month.slice(5))}월 ${mvpCategory==='game'?'게임':mvpCategory==='study'?'학습':'종합'} MVP</h3></div><button class="btn secondary small" data-room>반 코드 ${esc(data.room.code)}</button></div>${winners.length?`<div class="podium">${winners.map((r,i)=>`<div class="podium-place ${r.rank===1?'first':r.rank===3?'third':''}"><span class="podium-crown">${r.rank===1?'♛':'✦'}</span><div class="podium-avatar">${avatar(r.avatar)}</div><strong>${esc(r.nickname)}</strong><div class="podium-block"><b>${r.rank}</b><span>${r.categoryPoints} XP</span></div></div>`).join('')}</div>`:'<div class="empty"><h3>이번 달 MVP 기록 없음</h3><p>학습·게임 완료 시 포인트 기록</p></div>'}${rows.map(r=>`<div class="ranking-row ${r.isMe?'mine':''}"><span class="rank-number">${r.rank||'–'}</span><div class="mini-avatar">${avatar(r.avatar)}</div><strong>${esc(r.nickname)} ${r.isMe?'<span class="chip green">나</span>':''}</strong><span class="rank-days">${r.activeDays}일</span><span class="rank-points">${r.categoryPoints}<small> XP</small></span></div>`).join('')}`;}catch(e){if(view==='rankings')$('#ranking-content').textContent=e.message;}}
function profile(){const keys=[['skin','털·피부색',6],['hair','무늬·헤어',6],['eyes','눈 모양',4],['outfit','옷 스타일',6],['color','컬러',8],['accessory','소품',6]];$('#app').innerHTML=`<div class="section-head"><div><p class="eyebrow">CHARACTER</p><h2>캐릭터</h2><p>종류·색상·옷·소품 설정</p></div><span class="chip">${state.user?.coins||0} C 보유</span></div>${!state.authenticated?loginNotice():''}<div class="grid-2 avatar-builder"><section class="panel character-panel"><div class="section-head"><span class="eyebrow">CHARACTER PREVIEW</span><span class="chip green">Lv.${state.user?.level||1}</span></div><div class="avatar-preview" id="avatar-preview">${avatar(draft)}</div><h3 id="nickname-preview">${esc(state.user?.nickname||'학습자')}</h3><p>다음 레벨까지 ${250-((state.user?.totalPoints||0)%250)} XP</p><div class="progress-track"><span style="width:${((state.user?.totalPoints||0)%250)/2.5}%"></span></div><button class="btn secondary full" data-random-avatar>랜덤 설정</button></section><section class="panel"><label class="field">별명<input id="nickname" maxlength="16" data-fg-label="별명" required value="${esc(state.user?.nickname||'')}" placeholder="16자 이내의 별명" autocomplete="nickname"></label><div class="avatar-field"><strong>캐릭터 종류</strong><div class="character-species-grid">${window.CuteCharacters.names.map((name,i)=>`<button class="character-species ${Number(draft.species||0)===i?'active':''}" data-avatar-key="species" data-avatar-value="${i}" aria-pressed="${Number(draft.species||0)===i}">${avatar({...draft,species:i})}<span>${esc(name)}</span></button>`).join('')}</div></div>${keys.map(([key,label,n])=>`<div class="avatar-field"><strong>${label}</strong><div class="option-row">${Array.from({length:n},(_,i)=>`<button class="option ${draft[key]===i?'active':''} ${key==='skin'||key==='color'?'swatch':''}" data-avatar-key="${key}" data-avatar-value="${i}" aria-label="${label} ${i+1}" aria-pressed="${draft[key]===i}" ${key==='skin'||key==='color'?`style="--swatch:${(key==='skin'?['#f9d9bc','#edbe96','#d9a073','#bf8256','#94613e','#684734']:['#f6d98b','#f6b49c','#efb6a0','#9bcfee','#f4cb70','#ecaac0','#b9ddeb','#f2d6a0'])[i]}"`:''}>${key==='accessory'?['없음','안경','헤드폰','왕관','고양이 귀','모자'][i]+((state.shop.owned||[0,1,2]).includes(i)?'':` 🔒`):key==='color'||key==='skin'?'':String(i+1)}</button>`).join('')}</div></div>`).join('')}<button class="btn primary full" data-save-profile>캐릭터 저장 ${icon('arrow')}</button><p class="tiny">별명·캐릭터: 우리 반 랭킹 공개 · 이메일 비공개</p></section></div><section class="panel shop"><div class="section-head"><div><p class="eyebrow">ACCESSORY SHOP</p><h3>소품 상점</h3></div><span class="chip">${state.user?.coins||0} C</span></div><div class="grid-3">${[[3,'왕관','♛',150],[4,'고양이 귀','🐱',250],[5,'세이지 모자','🎩',400]].map(([id,name,emoji,price])=>`<article class="shop-item"><span>${emoji}</span><h4>${name}</h4><p>${price} C</p><button class="btn ${(state.shop.owned||[]).includes(id)?'secondary':'primary'} small" data-buy="${id}" ${(state.shop.owned||[]).includes(id)?'disabled':''}>${(state.shop.owned||[]).includes(id)?'보유 중':'코인으로 교환'}</button></article>`).join('')}</div><p class="tiny">하루 20분 학습 완료 시 최대 20 C · 소품 구매 시 랭킹 포인트 차감 없음</p></section><section class="panel"><p class="eyebrow">STUDY BADGES</p><h3>학습 배지</h3><div class="badge-grid">${[[1,'1일 학습','🌱'],[3,'3일 학습','🌿'],[7,'7일 학습','✨'],[20,'20일 학습','🏅']].map(([n,title,emoji])=>`<div class="badge-card ${(state.progress.activeDays||0)>=n?'earned':'locked'}"><span>${emoji}</span><strong>${title}</strong><small>이번 달 ${n}일 학습</small></div>`).join('')}</div></section>`;}
function modal(html,cls=''){closeModal(false);modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="dialog ${cls}" role="dialog" aria-modal="true" aria-label="영어 학습"><div class="dialog-head"><span class="eyebrow">AJ ENGLISH · SPEAKING PRACTICE</span><button class="icon-button" data-close aria-label="닫기">${icon('close')}</button></div>${html}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root button, #modal-root input')?.focus(),0);}
function closeModal(stop=true){gameEpoch++;if(stop&&session){saveLocalSession();session=null;}window.SpeakingCrateGame?.destroy();window.BusinessPractice?.destroy();stopAudio();clearInterval(timer);timer=null;$('#modal-root').innerHTML='';document.body.style.overflow='';if(modalReturn?.isConnected)modalReturn.focus();else $('#app')?.focus({preventScroll:true});}
function requireProfile(reason='학습 기록 저장'){if(!state.authenticated){modal(`<div class="dialog-body empty"><h2>${esc(reason)}</h2><p>${reason==='반 참여'?'로그인 → 별명·캐릭터 저장 → 반 코드 입력':'캐릭터·포인트 저장 시 로그인 필요 · 말하기 학습은 게스트 이용 가능'}</p><a class="btn primary" href="/login?return_to=%2F" target="_top">로그인 ↗</a><button class="btn secondary" data-business-demo>말하기 학습 시작</button></div>`,'small');return false;}if(!state.user){closeModal();navigate('profile');toast('별명·캐릭터 저장 필요');return false;}return true;}
function roomModal(){if(!requireProfile('반 참여'))return;modal(`<div class="dialog-body"><h2>우리 반</h2><p>반 코드로 연결된 로그인 사용자 간 랭킹 공유</p>${state.room?`<div class="room-code"><span>${esc(state.room.name)}</span><strong>${esc(state.room.code)}</strong><button class="btn secondary small" data-copy-code>반 코드 복사</button><p class="tiny">반 코드와 사이트 주소 함께 공유</p></div>`:''}<form id="join-room"><label class="field">반 코드<input name="code" required minlength="6" maxlength="6" pattern="[A-HJ-NP-Za-hj-np-z2-9]{6}" placeholder="예: ABC234" title="0·1·I·O를 제외한 영문·숫자 6자리" data-fg-label="반 코드" autocapitalize="characters" autocomplete="off"></label><p class="tiny">영문·숫자 6자리 · 0·1·I·O 제외</p><button class="btn primary full" type="submit">반 참여 ↗</button></form><div class="or-divider">새 반 등록</div><form id="create-room"><label class="field">우리 반 이름<input name="name" required maxlength="30" placeholder="예: AJ 주일 영어반" data-fg-label="반 이름"></label><button class="btn secondary full" type="submit">새 반 등록 +</button></form><p class="tiny">반 변경 시 기존 기록 유지 · 이후 포인트는 새 반에 반영</p><p id="room-error" class="error" role="alert"></p></div>`,'small');}
let voices=[];function refreshVoices(){voices=window.speechSynthesis?.getVoices().filter(v=>/^en[-_]/i.test(v.lang))||[];const s=$('#voice-select');if(s){const v=settings.voice;s.innerHTML='<option value="">자동 선택 (영어)</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)}</option>`).join('');s.value=v;}}
function stopAudio(){window.speechSynthesis?.cancel();}
function say(text){if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){toast('음성 읽기 미지원 · Chrome 또는 Edge에서 열기');return false;}stopAudio();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=Number(settings.speed)||0.85;u.voice=voices.find(v=>v.voiceURI===settings.voice)||voices.find(v=>v.lang==='en-US')||voices[0]||null;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('음성 재생 실패 · 영어 음성·기기 음량 확인');};window.speechSynthesis.speak(u);return true;}
function soundModal(){modal(`<div class="dialog-body"><h2>듣기 설정</h2><p>영어 음성·속도 설정</p><label class="field">영어 음성<select id="voice-select"></select></label><label class="field">읽기 속도<select id="speed-select"><option value="0.7">아주 천천히</option><option value="0.85">천천히</option><option value="1">보통</option></select></label><div class="sound-actions"><button class="btn primary" data-say="Please keep me in the loop.">${icon('play')} 소리 테스트</button><button class="btn secondary" data-stop-audio>■ 멈추기</button></div><details class="audio-help"><summary>소리 재생 문제 해결 · 안드로이드</summary><ol><li>미디어 음량·이어폰 연결 확인</li><li>다른 영어 음성 선택</li><li>기기 설정 → 텍스트 음성 변환 → 영어 음성 데이터 설치</li><li>Chrome에서 사이트 직접 열기</li></ol><p>기기 음성 엔진 사용 · 일부 음성은 인터넷 연결 필요</p></details><p class="tiny">말하기 학습: 마이크·브라우저 음성 인식 사용 · 제공업체의 음성 처리 가능</p></div>`,'small');refreshVoices();$('#speed-select').value=String(settings.speed);}
async function gameAnswer(run,index,answer){if(!run)return {points:0};for(let attempt=0;attempt<2;attempt++){try{return await api('activity/answer',{runId:run.runId,index,answer});}catch(error){if(attempt===0&&error.status===409&&Number(error.retryAfterMs)>0&&Number(error.retryAfterMs)<=8000){await new Promise(resolve=>setTimeout(resolve,Number(error.retryAfterMs)+30));continue;}toast('문제 보상 저장 실패 · '+error.message);return {points:0,saveFailed:true};}}return {points:0};}
async function gameRun(mode,sourceRunId){if(!state.authenticated||!state.user)return null;try{return await api('activity/start',{mode,...(sourceRunId?{sourceRunId}:{})});}catch(e){toast('포인트 연결 확인 실패 · 자유 연습으로 시작');return null;}}
async function finishGame(run,answers,selector){
  if(!run)return;
  const target=$(selector),epoch=gameEpoch,submitted=Array.isArray(answers)?answers.map(answer=>typeof answer==='object'?{...answer}:answer):answers;
  if(!target)return;
  target.querySelector('[data-game-save-status]')?.remove();
  try{
    let result;
    for(let attempt=0;attempt<2;attempt++){
      try{result=await api('activity/complete',{runId:run.runId,answers:submitted});break;}
      catch(error){
        if(attempt===0&&error.status===409&&Number(error.retryAfterMs)>0&&Number(error.retryAfterMs)<=8000){await new Promise(resolve=>setTimeout(resolve,Number(error.retryAfterMs)+30));continue;}
        throw error;
      }
    }
    await refresh();
    const box=$(selector);
    if(epoch!==gameEpoch||box!==target)return;
    box.querySelector('.game-reward')?.remove();
    box.insertAdjacentHTML('beforeend',`<div class="game-reward" role="status">${result.points>0?`퀘스트 완료 +${result.points} XP · +${result.coins} C`:result.alreadyFinished?'게임 기록 저장 완료':'오늘 게임 보상 한도 도달 · 연습 계속 가능'}</div>`);
    if(result.points>0)window.AJRewards?.show({anchor:box,points:result.points,progress:100,label:'퀘스트 완료'});
  }catch(error){
    if(epoch!==gameEpoch||$(selector)!==target)return;
    toast('완료 기록 저장 실패 · 같은 결과로 재시도');
    const panel=document.createElement('div');panel.className='game-reward';panel.setAttribute('data-game-save-status','');panel.setAttribute('role','status');
    const text=document.createElement('p');text.textContent='완료 기록 미확인 · '+(error.message||'연결 확인 후 재시도');
    const button=document.createElement('button');button.type='button';button.className='btn secondary';button.textContent='완료 기록 저장 재시도';button.setAttribute('data-game-save-retry','');
    button.addEventListener('click',()=>{button.disabled=true;finishGame(run,submitted,selector);},{once:true});
    panel.append(text,button);target.querySelector('[data-game-save-status]')?.remove();target.appendChild(panel);
  }
}
async function businessDemo(){session=null;modal(`<div class="dialog-body"><div class="section-head"><div><p class="eyebrow">BUSINESS ENGLISH · SPEAKING</p><h2>말하기 학습</h2><p>최신 수업 표현 듣기 → 문장 전체 말하기</p></div><span class="chip green">게임 퀘스트</span></div><div id="business-game"><p>표현 불러오는 중</p></div><p class="tiny">문제별 첫 정답 +2 XP · 전체 완료 +4 XP · 하루 최대 40 게임 XP · 게스트 진행률 표시</p></div>`,'wide');const epoch=++gameEpoch,run=await gameRun('speaking');if(epoch!==gameEpoch||!$('#business-game'))return;const source=run?.challenge.cards||BUSINESS_DAYS[5].phrases,answers=[];const targets=source.map((d,i)=>({en:d.en,ko:d.ko,fruit:['orange','apple','grape'][i]}));window.SpeakingCrateGame.mount($('#business-game'),{targets,say,onPass:async(index,transcript)=>{const result=await gameAnswer(run,index,transcript);if(result.saveFailed&&run)return {passed:false};answers[index]=transcript;return {passed:true,points:Number(result.points)||0};},onComplete(){const box=$('#business-game');if(box)box.insertAdjacentHTML('beforeend',`<div class="game-complete"><h3>말하기 학습 완료</h3><p>수업 표현 3개 인식 완료</p><button class="btn primary" data-business-demo>새 게임</button><button class="btn secondary" data-demo-quest>20분 수업 복습 시작 ↗</button></div>`);finishGame(run,answers,'#business-game');}});}
async function practiceModal(mode){if(!['arrange','listening'].includes(mode))return;session=null;modal(`<div class="dialog-body"><div id="practice-game"><p>최신 수업 표현 불러오는 중</p></div></div>`,'wide');const epoch=++gameEpoch;let run=await gameRun(mode),rewardRun=Promise.resolve(run),sourceRunId=run?.runId;if(epoch!==gameEpoch||!$('#practice-game'))return;window.BusinessPractice.mount($('#practice-game'),{mode,phrases:run?.challenge.cards,say,onAnswer:async detail=>gameAnswer(await rewardRun,detail.index,detail.answer),async onComplete(detail){finishGame(await rewardRun,detail.answers,'#practice-game');},onRestart(){rewardRun=gameRun(mode,sourceRunId).then(next=>{run=next;return next;});}});}
function saveLocalSession(){if(!session)return;try{sessionStorage.setItem('lil-session',JSON.stringify({id:session.id,step:session.step,phrase:session.phrase,qi:session.qi,reflection:session.reflection||"",listened:session.listened||[],conversationDone:session.conversationDone===true}));}catch{}}
async function startLesson(day){if(!requireProfile('20분 복습'))return;try{const d=await api('session/start',{day:Number(day),course,replaceLegacyFruit:course==='business'});session={...d.session,step:0,phrase:0,qi:0};course=session.course;try{const old=JSON.parse(sessionStorage.getItem('lil-session')||'null');if(old?.id===session.id)Object.assign(session,{step:Math.min(3,old.step||0),phrase:old.phrase||0,qi:old.qi||0,reflection:old.reflection||"",listened:Array.isArray(old.listened)?old.listened:[],conversationDone:old.conversationDone===true});}catch{}openSession();}catch(e){toast(e.message);}}
function openSession(){const keep=session;modal(`<div id="session-content"></div>`,'wide session');session=keep;renderSession();timer=setInterval(updateTimer,1000);}
function updateTimer(){if(!session)return;const elapsed=Math.max(0,Math.floor((Date.now()-session.startedAt)/1000));document.querySelectorAll('[data-session-timer]').forEach(el=>el.textContent=fmtTime(elapsed));document.querySelectorAll('[data-session-remaining]').forEach(el=>el.textContent=fmtTime(Math.max(0,1200-elapsed)));}
function sessionProgress(){if(!session)return 0;const d=session.lesson||COURSE_DATA[session.course].find(x=>x.id===session.day);const listen=new Set(session.listened||[]).size/Math.max(1,d.phrases.length)*20;const speech=new Set(session.speechPassed||[]).size/Math.max(1,d.phrases.length)*40;const conversation=session.conversationDone?10:0;const quiz=(session.answers||[]).length/Math.max(1,d.quiz.length)*30;return Math.min(100,Math.round(listen+speech+conversation+quiz));}
function updateSessionProgress(){const value=sessionProgress();const fill=$('[data-session-progress]'),label=$('[data-session-percent]');if(fill)fill.style.width=value+'%';if(label)label.textContent=value+'%';return value;}
function renderSession(){if(!session)return;window.SpeakingCrateGame?.destroy();stopAudio();saveLocalSession();const d=session.lesson||COURSE_DATA[session.course].find(d=>d.id===session.day),s=session,labels=['듣기','말하기','대화 연습','퀴즈'];let html='';if(s.step===0){const p=d.phrases[s.phrase%d.phrases.length];html=`<p class="eyebrow">STEP 01 · 5분 · LISTENING</p><h2>표현 듣기</h2><p>표현 듣기 → 3회 따라 말하기 → 뜻 없이 복습</p><div class="phrase-card"><span class="chip">${s.phrase+1} / ${d.phrases.length}</span><h3 lang="en">${esc(p.en)}</h3><p>${esc(p.ko)}</p><button class="btn primary" data-say="${esc(p.en)}">${icon('sound')} 듣고 따라 말하기</button><div class="card-note">${esc(p.note||'듣기 후 3회 말하기')}</div></div><div class="session-actions"><button class="btn secondary" data-phrase-prev ${s.phrase===0?'disabled':''}>← 이전 표현</button><button class="btn secondary" data-phrase-next>다음 표현 →</button></div>`;}else if(s.step===1){html=`<p class="eyebrow">STEP 02 · 5분 · SPEAKING</p><h2>말하기 학습</h2><p>문장 전체 인식 시 과일 1개 추가 · 3개 표현으로 상자 완성</p><div id="session-game"></div>`;}else if(s.step===2){html=`<p class="eyebrow">STEP 03 · 7분 · CONVERSATION</p><h2>대화 연습</h2><div class="speech-dialogue">${d.dialogue.map((r,i)=>`<div class="speech-line ${i%2?'you':''}"><span class="speech-role">${i%2?'나':'파트너'}</span><div class="speech-bubble"><p lang="en">${esc(r.en)}</p><small>${esc(r.ko)}</small><button class="icon-button" data-say="${esc(r.en)}" aria-label="대화 듣기">${icon('sound')}</button></div></div>`).join('')}</div><div class="speaking-prompt"><b>개인 말하기 과제</b><p>${esc(d.prompt)}</p><details><summary>예문 확인</summary><p lang="en">${esc(d.example)}</p></details></div><label class="field">수업 문장 메모<textarea id="reflection" maxlength="500" placeholder="이름·직업·목표에 맞는 문장 입력">${esc(s.reflection||'')}</textarea></label>`;}else{const qi=Math.min(s.qi,2),q=d.quiz[qi],answer=s.answers.find(a=>a.questionIndex===qi);html=`<p class="eyebrow">STEP 04 · 3분 · CHECK YOUR MEMORY</p><h2>복습 퀴즈</h2><p>오늘의 퀴즈 ${qi+1} / ${d.quiz.length}</p><div class="quiz-question">${esc(q.q)}</div><div class="quiz-options">${q.options.map((o,i)=>`<button class="quiz-option ${answer?(i===q.answer?'correct':i===answer.answerIndex?'wrong':''):''}" data-quiz-answer="${i}" ${answer?'disabled':''}><span class="option-letter">${['A','B','C'][i]}</span>${esc(o)}${answer&&i===q.answer?icon('check'):''}</button>`).join('')}</div>${answer?`<div class="feedback ${answer.correct?'success':''}"><strong>${answer.correct?'정답':'오답 · 해설 확인'}</strong><p>${esc(q.explanation)}</p></div>`:''}<p class="tiny">답 선택 후 해설 표시 · 최초 답변 기준 보상</p>`;}
if(d.note)html='<p class="tiny">'+esc(d.note)+'</p>'+html;const speechDone=(s.speechPassed||[]).length>=d.phrases.length;const quizDone=s.answers.length>=d.quiz.length;$('#session-content').innerHTML=`<div class="session-top"><div><span class="day-label">${courseNames[s.course]} · DAY ${s.day}</span><strong>${esc(d.title)}</strong></div><div class="timer">${icon('clock')} <span data-session-timer>00:00</span><small>/ 20:00</small></div></div><div class="steps">${labels.map((x,i)=>`<span class="step ${s.step===i?'active':s.step>i?'done':''}"><b>${s.step>i?'✓':i+1}</b>${x}</span>`).join('')}</div><div class="aj-session-hud"><span>퀘스트 진행</span><div class="aj-session-progress"><i data-session-progress style="width:${sessionProgress()}%"></i></div><strong data-session-percent>${sessionProgress()}%</strong></div><div class="dialog-body session-body">${html}</div><div class="dialog-footer"><button class="btn secondary" data-step-back ${s.step===0?'disabled':''}>← 이전 단계</button>${s.step===3?`<button class="btn primary" ${s.qi<2?'data-next-quiz':'data-finish'} ${s.qi<2?!s.answers.find(a=>a.questionIndex===s.qi)?'disabled':'':!quizDone||!speechDone?'disabled':''}>${s.qi<2?'다음 문제 →':'학습 완료'}</button>`:`<button class="btn primary" data-step-next ${s.step===1&&!speechDone?'disabled':''}>다음 연습 ${icon('arrow')}</button>`}</div>`;updateTimer();if(s.step===1){window.SpeakingCrateGame.mount($('#session-game'),{targets:d.phrases.map((p,i)=>({en:p.en,ko:p.ko,fruit:p.fruit||['orange','apple','banana'][i]})),initialPassed:s.speechPassed||[],say,onPass:async(index,transcript)=>{const r=await api('session/speech',{sessionId:s.id,index,transcript});if(session!==s)return {...r,passed:false};if(r.passed){s.speechPassed=[...new Set([...(s.speechPassed||[]),index])];saveLocalSession();updateSessionProgress();}return r;},onComplete(){const next=$('[data-step-next]');if(next)next.disabled=false;toast('표현 3개 인식 완료 · 다음 단계 진행 가능');}});}}
