document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{if(b.classList.contains('skip-link')){e.preventDefault();$('#app').focus();return;}if(b.hasAttribute('data-privacy-info')){privacyModal();return;}if(b.hasAttribute('data-contact-info')){contactModal();return;}if(b.hasAttribute('data-storage-info')){storageModal();return;}if(b.hasAttribute('data-storage-profile')){closeModal();navigate('profile');return;}if(b.dataset.view){if(b.tagName==='A'&&(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button>0))return;e.preventDefault();navigate(b.dataset.view);return;}if(b.dataset.go){e.preventDefault();navigate(b.dataset.go);return;}if(b.dataset.openChapter){navigate('slides',{chapter:b.dataset.openChapter});return;}if(b.dataset.mvpTab){mvpCategory=b.dataset.mvpTab;rankings();return;}if(b.hasAttribute('data-close')){closeModal();return;}if(b.dataset.course){course=b.dataset.course;render();return;}if(b.dataset.practice){practiceModal(b.dataset.practice);return;}if(b.hasAttribute('data-practice-quest')){closeModal();course='business';startLesson(Number(b.dataset.practiceQuest)||nextDay().id);return;}if(b.hasAttribute('data-room')||b.id==='class-open'){roomModal();return;}if(b.hasAttribute('data-sound')||b.id==='sound-settings'){if(session){toast('현재 학습 창 종료 후 듣기 설정 변경 가능 · 학습 이어하기 지원');return;}soundModal();return;}if(b.hasAttribute('data-business-demo')){closeModal();businessDemo();return;}if(b.hasAttribute('data-demo-quest')){closeModal();course='business';startLesson(1);return;}if(b.dataset.start){await startLesson(b.dataset.start);return;}if(b.dataset.say){say(b.dataset.say);if(session&&session.step===0){const before=sessionProgress();session.listened=[...new Set([...(session.listened||[]),session.phrase])];const after=updateSessionProgress();saveLocalSession();if(after>before)window.AJRewards?.show({anchor:b,progress:after,deltaProgress:after-before,label:'듣기 확인'});}return;}if(b.hasAttribute('data-stop-audio')){stopAudio();return;}if(b.hasAttribute('data-copy-code')){try{await navigator.clipboard.writeText(state.room.code);toast('반 코드 복사 완료');}catch{toast('반 코드: '+state.room.code);}return;}if(b.hasAttribute('data-save-note')){try{localStorage.setItem('lil-class-note',$('#class-note').value);toast('수업 메모 기기 저장 완료');}catch{toast('브라우저 메모 저장 불가');}return;}if(b.dataset.filter){filter=b.dataset.filter;library();return;}if(b.dataset.saveExpression!==undefined||b.dataset.learn!==undefined){const d=[...BUSINESS_DATA,...DATA][Number(b.dataset.saveExpression??b.dataset.learn)];const list=b.dataset.learn!==undefined?learned:saved;const idx=list.indexOf(d.en);if(idx<0)list.push(d.en);else list.splice(idx,1);localSave();library();return;}if(b.dataset.avatarKey){const key=b.dataset.avatarKey,value=Number(b.dataset.avatarValue);if(key==='accessory'&&!state.shop.owned.includes(value)){toast('소품 상점에서 코인 교환 필요');return;}draft[key]=value;$('#avatar-preview').innerHTML=avatar(draft);document.querySelectorAll(`[data-avatar-key="${key}"]`).forEach(x=>{const on=Number(x.dataset.avatarValue)===value;x.classList.toggle('active',on);x.setAttribute('aria-pressed',on);});return;}if(b.hasAttribute('data-random-avatar')){for(const [key,n]of Object.entries({species:13,skin:6,hair:6,eyes:4,outfit:6,color:8}))draft[key]=Math.floor(Math.random()*n);draft.accessory=state.shop.owned[Math.floor(Math.random()*state.shop.owned.length)];const nick=$('#nickname').value;profile();$('#nickname').value=nick;return;}if(b.hasAttribute('data-save-profile')){if(!state.authenticated){requireProfile();return;}b.disabled=true;const r=await api('profile',{nickname:$('#nickname').value.trim(),avatar:draft});state.user=r.user;updateNav();toast('캐릭터 저장 완료');profile();return;}if(b.dataset.buy){if(!requireProfile())return;b.disabled=true;await api('shop',{accessory:Number(b.dataset.buy)});await refresh();profile();toast('소품 교환 완료 · 캐릭터에서 선택 가능');return;}if(b.hasAttribute('data-phrase-prev')){session.phrase=Math.max(0,session.phrase-1);renderSession();return;}if(b.hasAttribute('data-phrase-next')){session.phrase=(session.phrase+1)%3;renderSession();return;}if(b.hasAttribute('data-step-next')){if(session.step===2){const before=sessionProgress();session.reflection=$('#reflection')?.value||'';session.conversationDone=true;window.AJRewards?.show({anchor:b,progress:sessionProgress(),deltaProgress:sessionProgress()-before,label:'대화 연습 완료'});}if(session.step===1&&(session.speechPassed||[]).length<3)return;session.step=Math.min(3,session.step+1);renderSession();return;}if(b.hasAttribute('data-step-back')){if(session.step===2)session.reflection=$('#reflection')?.value||'';session.step=Math.max(0,session.step-1);renderSession();return;}if(b.dataset.quizAnswer!==undefined){const active=session;if(!active||active.quizBusy)return;active.quizBusy=true;document.querySelectorAll('[data-quiz-answer]').forEach(x=>x.disabled=true);try{const before=sessionProgress();const r=await api('session/quiz',{sessionId:active.id,index:active.qi,answer:Number(b.dataset.quizAnswer)});if(session!==active)return;active.answers=active.answers.filter(a=>a.questionIndex!==r.index);active.answers.push({questionIndex:r.index,answerIndex:r.answer,correct:r.correct});window.AJRewards?.show({anchor:b,progress:sessionProgress(),deltaProgress:sessionProgress()-before,label:r.correct?'정답':'답변 완료'});}finally{active.quizBusy=false;if(session===active)renderSession();}return;}if(b.hasAttribute('data-next-quiz')){session.qi++;renderSession();return;}if(b.hasAttribute('data-finish')){await finishLesson();return;}if(b.hasAttribute('data-confirm-finish')){b.disabled=true;await finishLesson(true);return;}if(b.hasAttribute('data-keep-practicing')){renderSession();return;}if(b.hasAttribute('data-finish-close')){closeModal();navigate('home');return;}if(b.hasAttribute('data-after-rankings')){closeModal();navigate('rankings');return;}}catch(err){b.disabled=false;toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.name==='code'&&e.target.closest('#join-room'))e.target.value=e.target.value.toUpperCase().replace(/\s/g,'');if(e.target.id==='library-search'){const pos=e.target.selectionStart;search=e.target.value;library();$('#library-search').focus();$('#library-search').setSelectionRange(pos,pos);}if(e.target.id==='nickname')$('#nickname-preview').textContent=e.target.value||'학습자';if(e.target.id==='reflection'&&session){session.reflection=e.target.value;saveLocalSession();}});
document.addEventListener('change',e=>{if(e.target.id==='voice-select'){settings.voice=e.target.value;localSave();}if(e.target.id==='speed-select'){settings.speed=Number(e.target.value);localSave();}if(e.target.id==='rank-month'&&e.target.value){rankMonth=e.target.value;rankings();}});
document.addEventListener('submit',async e=>{if(!['join-room','create-room'].includes(e.target.id))return;e.preventDefault();const form=e.target,b=form.querySelector('button');b.disabled=true;try{const data=new FormData(form);await api('room',form.id==='join-room'?{action:'join',code:data.get('code').trim().toUpperCase()}:{action:'create',name:data.get('name').trim()});await refresh();closeModal();navigate('rankings');toast('반 연결 완료');}catch(err){$('#room-error').textContent=err.message;b.disabled=false;}});
document.addEventListener('keydown',e=>{const m=$('#modal-root');if(!m.firstChild)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=[...m.querySelectorAll('button:not([disabled]),a,input,select,textarea,summary')].filter(x=>x.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('beforeunload',saveLocalSession);
window.addEventListener('pagehide',event=>{saveLocalSession();if(event.persisted)return;entryController?.destroy();window.SpeakingCrateGame?.destroy();window.BusinessPractice?.destroy();window.ArcadeExperience?.destroy();window.ArcadeEffects?.destroy();window.FlashcardStudy?.destroy();window.ClassroomSlides?.destroy();window.StudentDashboard?.destroy();questController?.destroy();railController?.destroy();window.AJRewards?.clear();stopAudio();});
if(window.speechSynthesis){refreshVoices();window.speechSynthesis.addEventListener('voiceschanged',refreshVoices);}
$('#today-date').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',weekday:'short'}).format(new Date());
view=ROUTE_VIEWS.includes(location.hash.slice(1))?location.hash.slice(1):'home';
initializeRouteHistory();
window.addEventListener('popstate',routeFromAddress);window.addEventListener('hashchange',routeFromAddress);
window.ArcadeEffects?.boot();
window.AJHelp?.init({role:'student',onNavigate:navigate});
(async()=>{await Promise.all([refresh(),loadTeaching(true)]);render();window.AJHelp?.maybeWelcome();contentPoll=setInterval(()=>{if(!document.hidden){loadTeaching();refreshForNewDay();}},5000);})();
window.addEventListener('focus',()=>{loadTeaching();refreshForNewDay();});document.addEventListener('visibilitychange',()=>{if(!document.hidden){loadTeaching();refreshForNewDay();}});window.addEventListener('storage',e=>{if(e.key==='maranatha-teaching-revision')loadTeaching();});if(window.BroadcastChannel){const updates=new BroadcastChannel('teaching-updates');updates.onmessage=()=>loadTeaching();}
